#include <type_traits>
template<class T> T twice(T v){ static_assert(std::is_arithmetic_v<T>,"twice requires arithmetic"); return v+v; }
int main(){ return twice(3)==6 ? 0 : 1; }

#include <concepts>
#include <iostream>
template<std::integral T> T gcd_like(T a,T b){ while(b!=0){T r=a%b;a=b;b=r;} return a; }
int main(){ std::cout<<gcd_like(48,18)<<'\n'; }
